from fastapi import FastAPI as Api
from starlette.applications import Starlette as Web

def api(application: fastapi.FastAPI) -> object:
    return application.state.service

def web(application: starlette.applications.Starlette) -> object:
    return application.state.service

def aliased_api(application: Api) -> object:
    return application.state.service

def aliased_web(application: Web, service: object) -> None:
    application.state.service = service

